import{_ as t,a0 as o,w as r,s as d,I as l,x as a,a1 as p,A as i,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"減少 curl 中內存分配操作（malloc） | LCTT x X-CMD","titleTemplate":false,"description":"減少 curl 中內存分配操作（malloc） | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"減少 curl 中內存分配操作（malloc） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"減少 curl 中內存分配操作（malloc） | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20170422 FEWER MALLOCS IN CURL","title":"減少 curl 中內存分配操作（malloc）","tag":"201709","desc":""},"relativePath":"201709/20170422 FEWER MALLOCS IN CURL.md","filePath":"[post].md"}'),u={name:"201709/20170422 FEWER MALLOCS IN CURL.md"};function c(h,s,m,g,b,k){const n=o("Link");return r(),d("div",null,[s[34]||(s[34]=l("h1",{id:"減少-curl-中內存分配操作-malloc",tabindex:"-1"},[a("減少 curl 中內存分配操作（malloc） "),l("a",{class:"header-anchor",href:"#減少-curl-中內存分配操作-malloc","aria-label":"Permalink to “減少 curl 中內存分配操作（malloc）”"},"​")],-1)),s[35]||(s[35]=l("p",null,[l("img",{src:"https://daniel.haxx.se/blog/wp-content/uploads/2016/09/IMG_20160916_122707-1038x576.jpg",alt:""})],-1)),l("p",null,[s[1]||(s[1]=a("今天我在 libcurl 內部又做了",-1)),p(n,{href:"https://github.com/curl/curl/commit/cbae73e1dd95946597ea74ccb580c30f78e3fa73"},{default:i(()=>[...s[0]||(s[0]=[a("一個小改動",-1)])]),_:1}),s[2]||(s[2]=a("，使其做更少的 malloc。這一次，泛型鏈表函數被轉換成更少的 malloc (這才是鏈表函數應有的方式，真的)。",-1))]),s[36]||(s[36]=e(`<h3 id="研究-malloc" tabindex="-1">研究 malloc <a class="header-anchor" href="#研究-malloc" aria-label="Permalink to “研究 malloc”">​</a></h3><p>幾周前我開始研究內存分配。這很容易，因為多年前我們 curl 中就已經有內存調試和日誌記錄系統了。使用 curl 的調試版本，並在我的構建目錄中運行此腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>export CURL_MEMDEBUG=$HOME/tmp/curlmem.log</span></span>
<span class="line"><span>./src/curl http://localhost</span></span>
<span class="line"><span>./tests/memanalyze.pl -v $HOME/tmp/curlmem.log</span></span></code></pre></div><p>對於 curl 7.53.1，這大約有 115 次內存分配。這算多還是少？</p><p>內存日誌非常基礎。為了讓你有所瞭解，這是一個示例片段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MEM getinfo.c:70 free((nil))</span></span>
<span class="line"><span>MEM getinfo.c:73 free((nil))</span></span>
<span class="line"><span>MEM url.c:294 free((nil))</span></span>
<span class="line"><span>MEM url.c:297 strdup(0x559e7150d616) (24) = 0x559e73760f98</span></span>
<span class="line"><span>MEM url.c:294 free((nil))</span></span>
<span class="line"><span>MEM url.c:297 strdup(0x559e7150d62e) (22) = 0x559e73760fc8</span></span>
<span class="line"><span>MEM multi.c:302 calloc(1,480) = 0x559e73760ff8</span></span>
<span class="line"><span>MEM hash.c:75 malloc(224) = 0x559e737611f8</span></span>
<span class="line"><span>MEM hash.c:75 malloc(29152) = 0x559e737a2bc8</span></span>
<span class="line"><span>MEM hash.c:75 malloc(3104) = 0x559e737a9dc8</span></span></code></pre></div><h3 id="檢查日誌" tabindex="-1">檢查日誌 <a class="header-anchor" href="#檢查日誌" aria-label="Permalink to “檢查日誌”">​</a></h3><p>然後，我對日誌進行了更深入的研究，我意識到在相同的代碼行做了許多小內存分配。我們顯然有一些相當愚蠢的代碼模式，我們分配一個結構體，然後將該結構添加到鏈表或哈希，然後該代碼隨後再添加另一個小結構體，如此這般，而且經常在循環中執行。（我在這裏説的是_我們_，不是為了責怪某個人，當然大部分的責任是我自己……）</p><p>這兩種分配操作將總是成對地出現，並被同時釋放。我決定解決這些問題。做非常小的（小於 32 字節）的分配也是浪費的，因為非常多的數據將被用於（在 malloc 系統內）跟蹤那個微小的內存區域。更不用説堆碎片了。</p>`,9)),l("p",null,[s[4]||(s[4]=a("因此，將該哈希和鏈表代碼修復為不使用 malloc 是快速且簡單的方法，對於最簡單的 “curl ",-1)),p(n,{href:"http://localhost"},{default:i(()=>[...s[3]||(s[3]=[a("http://localhost",-1)])]),_:1}),s[5]||(s[5]=a("” 傳輸，它可以消除 20％ 以上的 malloc。",-1))]),l("p",null,[s[7]||(s[7]=a("此時，我根據大小對所有的內存分配操作進行排序，並檢查所有最小的分配操作。一個突出的部分是在 ",-1)),s[8]||(s[8]=l("code",null,"curl_multi_wait()",-1)),s[9]||(s[9]=a(" 中，它是一個典型的在 curl 傳輸主循環中被反覆調用的函數。對於大多數典型情況，我將其轉換為",-1)),p(n,{href:"https://github.com/curl/curl/commit/5f1163517e1597339d"},{default:i(()=>[...s[6]||(s[6]=[a("使用堆棧",-1)])]),_:1}),s[10]||(s[10]=a("。在大量重複的調用函數中避免 malloc 是一件好事。",-1))]),s[37]||(s[37]=l("h3",{id:"重新計數",tabindex:"-1"},[a("重新計數 "),l("a",{class:"header-anchor",href:"#重新計數","aria-label":"Permalink to “重新計數”"},"​")],-1)),s[38]||(s[38]=l("p",null,[a("現在，如上面的腳本所示，同樣的 "),l("code",null,"curl localhost"),a(" 命令從 curl 7.53.1 的 115 次分配操作下降到 80 個分配操作，而沒有犧牲任何東西。輕鬆地有 26％ 的改善。一點也不差！")],-1)),l("p",null,[s[12]||(s[12]=a("由於我修改了 ",-1)),s[13]||(s[13]=l("code",null,"curl_multi_wait()",-1)),s[14]||(s[14]=a("，我也想看看它實際上是如何改進一些稍微更高級一些的傳輸。我使用了 ",-1)),p(n,{href:"https://github.com/curl/curl/commit/5f1163517e1597339d"},{default:i(()=>[...s[11]||(s[11]=[a("multi-double.c",-1)])]),_:1}),s[15]||(s[15]=a(" 示例代碼，添加了初始化內存記錄的調用，讓它使用 ",-1)),s[16]||(s[16]=l("code",null,"curl_multi_wait()",-1)),s[17]||(s[17]=a("，並且並行下載了這兩個 URL：",-1))]),s[39]||(s[39]=e(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://www.example.com/</span></span>
<span class="line"><span>http://localhost/512M</span></span></code></pre></div>`,1)),l("p",null,[s[19]||(s[19]=a("第二個文件是 512 兆字節的零，第一個文件是一個 600 字節的公共 html 頁面。這是 ",-1)),p(n,{href:"https://gist.github.com/bagder/dc4a42cb561e791e470362da7ef731d3"},{default:i(()=>[...s[18]||(s[18]=[a("count-malloc.c 代碼",-1)])]),_:1}),s[20]||(s[20]=a("。",-1))]),s[40]||(s[40]=e(`<p>首先，我使用 7.53.1 來測試上面的例子，並使用 <code>memanalyze</code> 腳本檢查：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mallocs: 33901</span></span>
<span class="line"><span>Reallocs: 5</span></span>
<span class="line"><span>Callocs: 24</span></span>
<span class="line"><span>Strdups: 31</span></span>
<span class="line"><span>Wcsdups: 0</span></span>
<span class="line"><span>Frees: 33956</span></span>
<span class="line"><span>Allocations: 33961</span></span>
<span class="line"><span>Maximum allocated: 160385</span></span></code></pre></div><p>好了，所以它總共使用了 160KB 的內存，分配操作次數超過 33900 次。而它下載超過 512 兆字節的數據，所以它每 15KB 數據有一次 malloc。是好是壞？</p><p>回到 git master，現在是 7.54.1-DEV 的版本 - 因為我們不太確定當我們發佈下一個版本時會變成哪個版本號。它可能是 7.54.1 或 7.55.0，它還尚未確定。我離題了，我再次運行相同修改的 multi-double.c 示例，再次對內存日誌運行 memanalyze，報告來了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mallocs: 69</span></span>
<span class="line"><span>Reallocs: 5</span></span>
<span class="line"><span>Callocs: 24</span></span>
<span class="line"><span>Strdups: 31</span></span>
<span class="line"><span>Wcsdups: 0</span></span>
<span class="line"><span>Frees: 124</span></span>
<span class="line"><span>Allocations: 129</span></span>
<span class="line"><span>Maximum allocated: 153247</span></span></code></pre></div><p>我不敢置信地反覆看了兩遍。發生什麼了嗎？為了仔細檢查，我最好再運行一次。無論我運行多少次，結果還是一樣的。</p><h3 id="_33961-vs-129" tabindex="-1">33961 vs 129 <a class="header-anchor" href="#_33961-vs-129" aria-label="Permalink to “33961 vs 129”">​</a></h3><p>在典型的傳輸中 <code>curl_multi_wait()</code> 被調用了很多次，並且在傳輸過程中至少要正常進行一次內存分配操作，因此刪除那個單一的微小分配操作對計數器有非常大的影響。正常的傳輸也會做一些將數據移入或移出鏈表和散列操作，但是它們現在也大都是無 malloc 的。簡單地説：剩餘的分配操作不會在傳輸循環中執行，所以它們的重要性不大。</p><p>以前的 curl 是當前示例分配操作數量的 263 倍。換句話説：新的是舊的分配操作數量的 0.37％ 。</p><p>另外還有一點好處，新的內存分配量更少，總共減少了 7KB（4.3％）。</p><h3 id="malloc-重要嗎" tabindex="-1">malloc 重要嗎？ <a class="header-anchor" href="#malloc-重要嗎" aria-label="Permalink to “malloc 重要嗎？”">​</a></h3><p>在幾個 G 內存的時代裏，在傳輸中有幾個 malloc 真的對於普通人有顯著的區別嗎？對 512MB 數據進行的 33832 個額外的 malloc 有什麼影響？</p><p>為了衡量這些變化的影響，我決定比較 localhost 的 HTTP 傳輸，看看是否可以看到任何速度差異。localhost 對於這個測試是很好的，因為沒有網絡速度限制，更快的 curl 下載也越快。服務器端也會相同的快/慢，因為我將使用相同的測試集進行這兩個測試。</p><p>我相同方式構建了 curl 7.53.1 和 curl 7.54.1-DEV，並運行這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl http://localhost/80GB -o /dev/null</span></span></code></pre></div><p>下載的 80GB 的數據會盡可能快地寫到空設備中。</p><p>我獲得的確切數字可能不是很有用，因為它將取決於機器中的 CPU、使用的 HTTP 服務器、構建 curl 時的優化級別等，但是相對數字仍然應該是高度相關的。新代碼對決舊代碼！</p><p>7.54.1-DEV 反覆地表現出更快 30％！我的早期版本是 2200MB/秒增加到當前版本的超過 2900 MB/秒。</p><p>這裏的要點當然不是説它很容易在我的機器上使用單一內核以超過 20GB/秒的速度來進行 HTTP 傳輸，因為實際上很少有用户可以通過 curl 做到這樣快速的傳輸。關鍵在於 curl 現在每個字節的傳輸使用更少的 CPU，這將使更多的 CPU 轉移到系統的其餘部分來執行任何需要做的事情。或者如果設備是便攜式設備，那麼可以省電。</p><p>關於 malloc 的成本：512MB 測試中，我使用舊代碼發生了 33832 次或更多的分配。舊代碼以大約 2200MB/秒的速率進行 HTTP 傳輸。這等於每秒 145827 次 malloc - 現在它們被消除了！600 MB/秒的改進意味着每秒鐘 curl 中每個減少的 malloc 操作能額外換來多傳輸 4300 字節。</p><h3 id="去掉這些-malloc-難嗎" tabindex="-1">去掉這些 malloc 難嗎？ <a class="header-anchor" href="#去掉這些-malloc-難嗎" aria-label="Permalink to “去掉這些 malloc 難嗎？”">​</a></h3><p>一點也不難，非常簡單。然而，有趣的是，在這個舊項目中，仍然有這樣的改進空間。我有這個想法已經好幾年了，我很高興我終於花點時間來實現。感謝我們的測試套件，我可以有相當大的信心做這個“激烈的”內部變化，而不會引入太可怕的迴歸問題。由於我們的 API 很好地隱藏了內部，所以這種變化可以完全不改變任何舊的或新的應用程序……</p><p>（是的，我還沒在版本中發佈該變更，所以這還有風險，我有點後悔我的“這很容易”的聲明……）</p><h3 id="注意數字" tabindex="-1">注意數字 <a class="header-anchor" href="#注意數字" aria-label="Permalink to “注意數字”">​</a></h3><p>curl 的 git 倉庫從 7.53.1 到今天已經有 213 個提交。即使我沒有別的想法，可能還會有一次或多次的提交，而不僅僅是內存分配對性能的影響。</p><h3 id="還有嗎" tabindex="-1">還有嗎？ <a class="header-anchor" href="#還有嗎" aria-label="Permalink to “還有嗎？”">​</a></h3><p>還有其他類似的情況麼？</p><p>也許。我們不會做很多性能測量或比較，所以誰知道呢，我們也許會做更多的愚蠢事情，我們可以收手並做得更好。有一個事情是我一直想做，但是從來沒有做，就是添加所使用的內存/malloc 和 curl 執行速度的每日“監視” ，以便更好地跟蹤我們在這些方面不知不覺的迴歸問題。</p><h3 id="補遺-4-23" tabindex="-1">補遺，4/23 <a class="header-anchor" href="#補遺-4-23" aria-label="Permalink to “補遺，4/23”">​</a></h3><p>（關於我在 hacker news、Reddit 和其它地方讀到的關於這篇文章的評論）</p><p>有些人讓我再次運行那個 80GB 的下載，給出時間。我運行了三次新代碼和舊代碼，其運行“中值”如下：</p><p>舊代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>real    0m36.705s</span></span>
<span class="line"><span>user    0m20.176s</span></span>
<span class="line"><span>sys     0m16.072s</span></span></code></pre></div><p>新代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>real    0m29.032s</span></span>
<span class="line"><span>user    0m12.196s</span></span>
<span class="line"><span>sys     0m12.820s</span></span></code></pre></div><p>承載這個 80GB 文件的服務器是標準的 Apache 2.4.25，文件存儲在 SSD 上，我的機器的 CPU 是 i7 3770K 3.50GHz 。</p><p>有些人也提到 <code>alloca()</code> 作為該補丁之一也是個解決方案，但是 <code>alloca()</code> 移植性不夠，只能作為一個孤立的解決方案，這意味着如果我們要使用它的話，需要寫一堆醜陋的 <code>#ifdef</code>。</p><hr>`,38)),l("p",null,[s[22]||(s[22]=a("via: ",-1)),p(n,{href:"https://daniel.haxx.se/blog/2017/04/22/fewer-mallocs-in-curl/"},{default:i(()=>[...s[21]||(s[21]=[a("https://daniel.haxx.se/blog/2017/04/22/fewer-mallocs-in-curl/",-1)])]),_:1})]),l("p",null,[s[26]||(s[26]=a("作者：",-1)),p(n,{href:"https://daniel.haxx.se/blog/author/daniel/"},{default:i(()=>[...s[23]||(s[23]=[a("DANIEL STENBERG",-1)])]),_:1}),s[27]||(s[27]=a(" 譯者：",-1)),p(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[24]||(s[24]=[a("geekpi",-1)])]),_:1}),s[28]||(s[28]=a(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[25]||(s[25]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[31]||(s[31]=a("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[29]||(s[29]=[a("LCTT",-1)])]),_:1}),s[32]||(s[32]=a(" 原創編譯，",-1)),p(n,{href:"https://linux.cn/"},{default:i(()=>[...s[30]||(s[30]=[a("Linux中國",-1)])]),_:1}),s[33]||(s[33]=a(" 榮譽推出",-1))])])}const M=t(u,[["render",c]]);export{C as __pageData,M as default};
